'use strict';
const STOPS={dinc:{code:'200051',title:'Dinç Sokak',short:'Dinç Sokak',match:'DİNÇ SOKAK'},berrak:{code:'224031',title:'Berrak Sitesi',short:'Berrak',match:'ŞENOL GÜNEŞ BULVARI'}};
const $=id=>document.getElementById(id);
const statusEl=$('status'),listEl=$('vehicles'),refreshButton=$('refresh'),moreEl=$('more'),descEl=$('stop-description'),sourceEl=$('source');
const stopButtons=Array.from(document.querySelectorAll('[data-stop]'));
let selected='dinc',generation=0,controller=null;
try{const stored=localStorage.getItem('dinc13-v2-stop');if(stored&&Object.prototype.hasOwnProperty.call(STOPS,stored))selected=stored;}catch(e){}
function setStopUI(){
 for(const b of stopButtons)b.setAttribute('aria-pressed',String(b.dataset.stop===selected));
 descEl.textContent=selected==='berrak'?'İETT: Şenol Güneş Bulvarı · 224031':'Dinç Sokak · 200051';
 sourceEl.href='https://iettapi.pcislocked.net/v1/stops/'+STOPS[selected].code+'/arrivals';
}
function xy(lat,lon,baseLat,baseLon){return [(lon-baseLon)*111320*Math.cos(baseLat*Math.PI/180),(lat-baseLat)*111320];}
function projection(bus,p,q){
 const [ax,ay]=xy(p[1],p[2],bus.latitude,bus.longitude);
 const [bx,by]=xy(q[1],q[2],bus.latitude,bus.longitude);
 const dx=bx-ax,dy=by-ay,den=dx*dx+dy*dy;
 const t=den?Math.max(0,Math.min(1,-(ax*dx+ay*dy)/den)):0;
 return {distance:Math.hypot(ax+t*dx,ay+t*dy),t};
}
function remainingStops(bus,stop){
 if(!Number.isFinite(bus.latitude)||!Number.isFinite(bus.longitude))return null;
 const matches=[];
 for(const route of ROUTES){
  const idx=route.points.findIndex(p=>p[0]===stop.match);
  if(idx<1)continue;
  const pts=route.points.slice(0,idx+1);
  let best=null;
  for(let i=0;i<pts.length-1;i++){
   const projectionData=projection(bus,pts[i],pts[i+1]);
   if(!best||projectionData.distance<best.distance)best={...projectionData,i};
  }
  if(best){
   matches.push({variant:route.id,distance:best.distance,
    remaining:idx-best.i,nextName:pts[best.i+1][0],
    suffix:pts.slice(Math.max(0,idx-4)).map(p=>p[0])});
  }
 }
 if(!matches.length)return null;
 matches.sort((a,b)=>a.distance-b.distance);
 const bestDist=matches[0].distance;
 if(bestDist>250)return null;
 const candidates=matches.filter(x=>x.distance<=Math.min(250,bestDist+75));
 const counts=candidates.map(x=>x.remaining);
 // Keep only the final stop names shared by all plausible route variants.
 const reversed=[];
 for(let offset=1;offset<=5;offset++){
  const names=candidates.map(x=>x.suffix.at(-offset));
  if(names.some(n=>!n)||names.some(n=>n!==names[0]))break;
  reversed.push(names[0]);
 }
 const suffix=reversed.length?reversed.reverse():null;
 const nextNames=[...new Set(candidates.map(x=>x.nextName))];
 const nextName=nextNames.length===1?nextNames[0]:null;
 const canPlace=!!suffix&&!!nextName&&suffix.includes(nextName);
 return {min:Math.min(...counts),max:Math.max(...counts),
  suffix,nextName,canPlace,variantCount:candidates.length,distance:bestDist};
}
function ageSeconds(hms){
 if(!hms||!/^\d{2}:\d{2}:\d{2}$/.test(hms))return null;
 const [h,m,s]=hms.split(':').map(Number);
 if(h>23||m>59||s>59)return null;
 const now=new Date(),nowSec=now.getHours()*3600+now.getMinutes()*60+now.getSeconds(),seen=h*3600+m*60+s;
 let delta=nowSec-seen;
 if(delta>43200)delta-=86400;
 if(delta<-43200)delta+=86400;
 return delta;
}
function add(parent,tag,cls,value){
 const elem=document.createElement(tag);
 if(cls)elem.className=cls;
 if(value!==undefined)elem.textContent=String(value);
 parent.appendChild(elem);return elem;
}
// Preserve expanded card state during periodic data refreshes.
const expandedTracks=new Map();
function addVehicleMarker(parent,label){
 const marker=add(parent,'div','timeline-bus');
 add(marker,'span','timeline-bus-icon','🚌');
 add(marker,'span','',label);
 return marker;
}
function makeTrack(card,rem,stop,index,vehicleKey){
 const details=add(card,'details','track');
 details.open=expandedTracks.has(vehicleKey)?expandedTracks.get(vehicleKey):index===0;
 const summary=add(details,'summary','track-summary');
 add(summary,'span','','Son 5 durak · GPS tahmini');
 add(summary,'span','track-toggle','');
 details.addEventListener('toggle',()=>expandedTracks.set(vehicleKey,details.open));
 const body=add(details,'div','timeline');
 if(!rem.suffix){
  add(body,'p','timeline-warning','Güzergâh varyantı belirsiz. Son durakların sırası güvenilir biçimde gösterilemiyor.');
  return;
 }
 const suffix=rem.suffix;
 const at=rem.canPlace?suffix.indexOf(rem.nextName):-1;
 if(at<0){
  if(rem.min>suffix.length){
   addVehicleMarker(body,'Henüz gösterilen son duraklara ulaşmadı');
  }else{
   addVehicleMarker(body,'Konum kesinleştirilemedi');
   add(body,'p','timeline-warning','Birden fazla güzergâh olası. Otobüsün durak arası konumu gösterilmiyor.');
  }
 }
 if(suffix.length<5)add(body,'p','timeline-warning','Güzergâhların ortak kalan '+suffix.length+' durağı gösteriliyor; daha önceki duraklar farklı olabilir.');
 const line=add(body,'ol','timeline-stops');
 for(let i=0;i<suffix.length;i++){
  if(at===i){
   const markerHolder=add(line,'li','timeline-vehicle');
   addVehicleMarker(markerHolder,'Bu durağa yaklaşıyor');
  }
  const isGoal=i===suffix.length-1;
  const phase=at>=0&&i<at?' passed':at===i?' next':'';
  const li=add(line,'li','timeline-stop'+phase+(isGoal?' target':''));
  add(li,'span','timeline-dot',isGoal?'◎':phase===' passed'?'✓':'');
  add(li,'span','timeline-stop-name',isGoal?stop.title+' · biniş':suffix[i]);
 }
 add(body,'p','timeline-foot','Durak geçişleri gerçek kayıtlar değil, GPS konumundan yapılan tahminlerdir.');
}
function makeCard(bus,index,stop){
 const card=document.createElement('article');
 card.className='card'+(index===0?' primary':'');
 const header=add(card,'div','card-top'),info=add(header,'div','');
 add(info,'div','plate','Araç '+(bus.kapino||'—'));
 add(info,'div','plate',bus.plate||'Plaka bilinmiyor');
 const age=ageSeconds(bus.last_seen_ts);
 const stale=age!==null&&(age>240||age<-120);
 const minutes=Number(bus.eta_minutes);
 add(header,'div','eta',!stale&&Number.isFinite(minutes)&&minutes>=0?Math.round(minutes)+' dk':'— dk');
 if(stale){
  add(card,'div','rem','Veri eski');
  add(card,'div','detail','GPS zamanı: '+bus.last_seen_ts+' · Durak sayısı gösterilmiyor.');
  return card;
 }
 const rem=remainingStops({latitude:Number(bus.lat),longitude:Number(bus.lon)},stop);
 if(!rem){
  add(card,'div','rem','— durak');
  add(card,'div','detail','GPS konumu seçilen güzergâhla eşleşmedi.');
  return card;
 }
 const exact=rem.min===rem.max;
 add(card,'div','rem'+(exact?'':' range'),exact?'≈ '+rem.min+' durak':rem.min+'–'+rem.max+' durak');
 add(card,'div','detail',exact?'GPS tabanlı tahmin':'Güzergâh belirsiz · tahmini aralık');
 makeTrack(card,rem,stop,index,stop.code+':'+String(bus.kapino||bus.plate||index));
 return card;
}
function live13(arrivals){
 return arrivals.filter(b=>String(b.route_code).trim()==='13'&&String(b.destination||'').toLocaleUpperCase('tr-TR').includes('KADIKÖY')).sort((a,b)=>{
  const aEta=Number(a.eta_minutes),bEta=Number(b.eta_minutes);
  return (Number.isFinite(aEta)?aEta:Infinity)-(Number.isFinite(bEta)?bEta:Infinity);
 });
}
async function refresh(){
 const seq=++generation;
 if(controller)controller.abort();
 controller=new AbortController();
 const mine=controller,stop=STOPS[selected];
 refreshButton.disabled=true;refreshButton.textContent='…';
 statusEl.textContent=stop.title+' için canlı veriler alınıyor…';
 const timeout=setTimeout(()=>mine.abort(),12000);
 try{
  const url='https://iettapi.pcislocked.net/v1/stops/'+stop.code+'/arrivals';
  const response=await fetch(url,{cache:'no-store',headers:{Accept:'application/json'},signal:mine.signal});
  if(!response.ok)throw new Error('HTTP '+response.status);
  const data=await response.json();
  if(!Array.isArray(data))throw new Error('Beklenmeyen API yanıtı');
  if(seq!==generation)return;
  const buses=live13(data);
  listEl.replaceChildren();
  for(const [i,bus] of buses.slice(0,2).entries())listEl.appendChild(makeCard(bus,i,stop));
  if(!buses.length)add(listEl,'div','empty','Bu durakta şu anda yaklaşan 13 otobüsü bildirilmiyor.');
  const hidden=Math.max(0,buses.length-2);
  moreEl.hidden=!hidden;
  if(hidden)moreEl.textContent='+'+hidden+' araç daha var · ilk iki araç gösteriliyor';
  statusEl.textContent=new Date().toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})+' · '+buses.length+' yaklaşan araç';
 }catch(err){
  if(seq!==generation)return;
  listEl.replaceChildren();moreEl.hidden=true;
  add(listEl,'div','empty error','Canlı veri alınamadı. İnternet veya API erişimini kontrol et.');
  statusEl.textContent='Bağlantı hatası: '+(err&&err.name==='AbortError'?'Zaman aşımı':(err instanceof Error?err.message:'Bilinmiyor'));
 }finally{
  clearTimeout(timeout);
  if(seq===generation){controller=null;refreshButton.disabled=false;refreshButton.textContent='Yenile';}
 }
}
for(const b of stopButtons)b.addEventListener('click',()=>{
 const next=b.dataset.stop;
 if(!Object.prototype.hasOwnProperty.call(STOPS,next)||next===selected)return;
 selected=next;
 try{localStorage.setItem('dinc13-v2-stop',selected);}catch(e){}
 setStopUI();listEl.replaceChildren();moreEl.hidden=true;refresh();
});
refreshButton.addEventListener('click',refresh);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh();});
setInterval(()=>{if(document.visibilityState==='visible')refresh();},30000);
if('serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='localhost')){
 window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
}
setStopUI();refresh();
